import{_ as o,B as n,o as r,c as d,a8 as l,a as e,E as s,f as a}from"./chunks/framework.CNIpabDg.js";const v=JSON.parse('{"title":"System activity","description":"Native Xila system activity dashboard, its metrics, bounded demo workload and provider limitations.","frontmatter":{"layout":"doc","docType":"explanation","description":"Native Xila system activity dashboard, its metrics, bounded demo workload and provider limitations."},"headers":[],"relativePath":"explanation/architecture/executables/activity.md","filePath":"explanation/architecture/executables/activity.md","lastUpdated":1793145952000}'),c={name:"explanation/architecture/executables/activity.md"};function p(u,t,h,m,b,y){const i=n("CodeReference");return r(),d("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793145952000"},[t[4]||(t[4]=l('<h1 id="system-activity" tabindex="-1">System activity <a class="header-anchor" href="#system-activity" aria-label="Permalink to &quot;System activity&quot;">​</a></h1><p><strong>System activity</strong> is a native Xila graphical application from <a href="https://github.com/xila-project/applications" target="_blank" rel="noreferrer">Applications</a>, introduced with Core #535 and now mounted by the Platforms native runtime at <code>/applications/executables/activity</code>. It is <strong>not a WASI guest</strong>, and no separate WebAssembly binary is produced.</p><p>A fresh <strong>native</strong> seed includes a launcher shortcut. Existing disks are not replaced by new seeds; the application can instead be launched from Xila&#39;s Terminal if mounted:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/applications/executables/activity --interval-ms 250</span></span></code></pre></div><h2 id="what-the-dashboard-measures" tabindex="-1">What the dashboard measures <a class="header-anchor" href="#what-the-dashboard-measures" aria-label="Permalink to &quot;What the dashboard measures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Metric</th><th>Source and meaning</th></tr></thead><tbody><tr><td>Uptime</td><td>Monotonic time since Time manager initialization; UTC changes do not change it</td></tr><tr><td>Registered tasks</td><td>Entries in Task manager, including root/runtime tasks</td></tr><tr><td>Allocator used/capacity</td><td>Xila allocator, <strong>not</strong> process RSS, physical RAM or per-application allocation</td></tr><tr><td>CPU load / registered devices</td><td><strong>Unavailable</strong> until appropriate service providers are implemented</td></tr></tbody></table><p>Each metric is sampled separately, not as an atomic snapshot. The default update interval is 1,000 ms; <code>--interval-ms</code> accepts 100–10,000 ms, and the Refresh control cycles 250/1,000/2,000 ms.</p><h2 id="bounded-demonstration-workload" tabindex="-1">Bounded demonstration workload <a class="header-anchor" href="#bounded-demonstration-workload" aria-label="Permalink to &quot;Bounded demonstration workload&quot;">​</a></h2><p>A temporary 4,096-byte allocation is increased in small batches (up to 512 bytes per 25 ms) and stopped after ten seconds. The app can stop it sooner; closing the window or cancelling its task releases the buffer. It does not spawn another task or benchmark CPU load. Allocation failure is displayed in the UI rather than crashing Xila.</p><p>Native Linux headless smoke testing exercised uptime, task counts, changing allocator usage and close/stop behavior. It does <strong>not</strong> establish MCU telemetry correctness or memory/latency guarantees.</p><h2 id="source-and-tests" tabindex="-1">Source and tests <a class="header-anchor" href="#source-and-tests" aria-label="Permalink to &quot;Source and tests&quot;">​</a></h2>',11)),e("ul",null,[e("li",null,[s(i,{repo:"applications",path:"executables/activity/README.md"}),t[0]||(t[0]=a(" — actual metrics, options, smoke results and limitations.",-1))]),e("li",null,[s(i,{repo:"applications",path:"executables/activity/src/lib.rs"}),t[1]||(t[1]=a(" — sampling/event lifecycle.",-1))]),e("li",null,[s(i,{repo:"applications",path:"executables/activity/src/workload.rs"}),t[2]||(t[2]=a(" — bounded workload.",-1))]),e("li",null,[s(i,{repo:"platforms",path:"examples/native/src/main.rs"}),t[3]||(t[3]=a(" — native executable registration.",-1))])]),t[5]||(t[5]=e("p",null,[a("Run "),e("code",null,"cargo test -p xila-activity --lib"),a(" in Applications. To launch the actual UI, build guests and a fresh image through the "),e("a",{href:"/tutorials/native.html"},"native Platforms tutorial"),a(".")],-1))])}const f=o(c,[["render",p]]);export{v as __pageData,f as default};
